    /// Update definition/type-parameter tracking for `token_kind`.
    fn visit_token_kind(&self, definition_state: &mut DefinitionState, token_kind: TokenKind) {
        if self.tokens().is_empty() || self.is_comment_only() {
            return;
        }

        if !definition_state.in_class
            && !definition_state.in_function
            && !definition_state.in_type_alias
        {
            return;
        }

        let type_params = &mut definition_state.type_params;
        match token_kind {
            TokenKind::Lpar if type_params.before_type_params => {
                type_params.before_type_params = false;
                type_params.in_type_params = false;
                type_params.type_params_ended = true;
                type_params.inner_square_brackets = 0;
            }
            TokenKind::Lsqb => {
                if type_params.type_params_ended {
                    // Nested brackets after the type parameter list do not reopen it.
                } else if type_params.before_type_params {
                    type_params.before_type_params = false;
                    type_params.in_type_params = true;
                    type_params.type_params_ended = false;
                    type_params.inner_square_brackets = 0;
                } else if type_params.in_type_params {
                    type_params.inner_square_brackets += 1;
                }
            }
            TokenKind::Rsqb => {
                if type_params.in_type_params {
                    if type_params.inner_square_brackets == 0 {
                        type_params.before_type_params = false;
                        type_params.in_type_params = false;
                        type_params.type_params_ended = true;
                    } else {
                        type_params.inner_square_brackets -= 1;
                    }
                }
            }
            _ => {}
        }
    }
