#[derive(Debug, Clone)]
struct Line {
    flags: TokenFlags,
    tokens_start: u32,
    tokens_end: u32,
}

/// Keeps track of whether we are currently visiting a class or function definition in a
/// [`LogicalLine`]. If we are visiting a class or function, the struct also keeps track
/// of the [type parameters] of the class/function.
///
/// Call [`LogicalLine::visit_token_kind`] on the [`TokenKind`] of each
/// successive [`LogicalLineToken`] to ensure the state remains up to date.
///
/// [type parameters]: https://docs.python.org/3/reference/compound_stmts.html#type-params
#[derive(Debug, Clone, Copy)]
struct DefinitionState {
    in_class: bool,
    in_function: bool,
    in_type_alias: bool,
    type_params: TypeParamsState,
}

impl DefinitionState {
    fn not_in_definition() -> Self {
        Self {
            in_class: false,
            in_function: false,
            in_type_alias: false,
            type_params: TypeParamsState::default(),
        }
    }

    fn from_tokens<'a>(tokens: impl IntoIterator<Item = &'a LogicalLineToken>) -> Self {
        let mut token_kinds = tokens.into_iter().map(LogicalLineToken::kind);
        while let Some(token_kind) = token_kinds.next() {
            match token_kind {
                TokenKind::Indent | TokenKind::Dedent => continue,
                TokenKind::Class => {
                    return Self {
                        in_class: true,
                        in_function: false,
                        in_type_alias: false,
                        type_params: TypeParamsState::default(),
                    };
                }
                TokenKind::Def => {
                    return Self {
                        in_class: false,
                        in_function: true,
                        in_type_alias: false,
                        type_params: TypeParamsState::default(),
                    };
                }
                TokenKind::Async if matches!(token_kinds.next(), Some(TokenKind::Def)) => {
                    return Self {
                        in_class: false,
                        in_function: true,
                        in_type_alias: false,
                        type_params: TypeParamsState::default(),
                    };
                }
                TokenKind::Type => {
                    return Self {
                        in_class: false,
                        in_function: false,
                        in_type_alias: true,
                        type_params: TypeParamsState::default(),
                    };
                }
                _ => return Self::not_in_definition(),
            }
        }
        Self::not_in_definition()
    }

    const fn in_function_definition(self) -> bool {
        self.in_function
    }

    fn in_type_params(self) -> bool {
        self.type_params.in_type_params
    }
}

#[cfg(test)]
mod tests {
    use ruff_python_parser::parse_module;

    use crate::Locator;

    use super::LogicalLines;

    #[test]
    fn multi_line() {
        assert_logical_lines(
            r"
x = 1
y = 2
z = x + 1"
                .trim(),
            &["x = 1", "y = 2", "z = x + 1"],
        );
    }

    #[test]
    fn indented() {
        assert_logical_lines(
            r"
x = [
  1,
  2,
  3,
]
y = 2
z = x + 1"
                .trim(),
            &["x = [\n  1,\n  2,\n  3,\n]", "y = 2", "z = x + 1"],
        );
    }

    #[test]
    fn string_assignment() {
        assert_logical_lines("x = 'abc'".trim(), &["x = 'abc'"]);
    }

    #[test]
    fn function_definition() {
        assert_logical_lines(
            r"
def f():
  x = 1
f()"
            .trim(),
            &["def f():", "x = 1", "f()"],
        );
    }

    #[test]
    fn trivia() {
        assert_logical_lines(
            r#"
def f():
  """Docstring goes here."""
  # Comment goes here.
  x = 1
f()"#
                .trim(),
            &[
                "def f():",
                "\"\"\"Docstring goes here.\"\"\"",
                "",
                "x = 1",
                "f()",
            ],
        );
    }

    #[test]
    fn empty_line() {
        assert_logical_lines(
            r"
if False:

    print()
"
            .trim(),
            &["if False:", "print()", ""],
        );
    }

    fn assert_logical_lines(contents: &str, expected: &[&str]) {
        let parsed = parse_module(contents).unwrap();
        let locator = Locator::new(contents);
        let actual: Vec<String> = LogicalLines::from_tokens(parsed.tokens(), &locator)
            .into_iter()
            .map(|line| line.text_trimmed())
            .map(ToString::to_string)
            .collect();
        let expected: Vec<String> = expected.iter().map(ToString::to_string).collect();
        assert_eq!(actual, expected);
    }
}

